import { Component } from '@angular/core';
import { UsuarioService } from 'src/app/services/usuario.service';

@Component({
  selector: 'app-mostrar-usuario-loado',
  templateUrl: './mostrar-usuario-loado.component.html',
  styleUrls: ['./mostrar-usuario-loado.component.css']
})
export class MostrarUsuarioLoadoComponent {

  emailUsuario: string = '';

  constructor(private usuarioService: UsuarioService) { }

  ngOnInit(): void {
    this.usuarioService.usuarioActual$.subscribe(usuario => {
      this.emailUsuario = usuario ? usuario.email : 'No hay usuario logueado';
    });
  }


}
